 neutral=set()
 for r in range(A.shape[0]-2):
  for c in range(A.shape[1]-2):
   block=set((rr,cc) for rr in range(r,r+3) for cc in range(c,c+3))
   if all(A[p]==wall for p in block):
    attached=any((rr,cc) in pts for col,pts in sources for rr in range(r-1,r+4) for cc in range(c-1,c+4))
    if not attached:neutral|=block
 mask=(A==wall)
